<template>
	<view class="container">
		<u-loading-page :loading="true" v-if="load" fontSize="28rpx" />
		<block v-else>
			<view class="denglu" v-if="user_id == 0" @click="showLogin">
				<button class="login-btn">立即登录</button>
			</view>
			<block v-else-if="lists.length>0">
				<scroll-view scroll-y="true" class="scroll">
					<view class="cart-container">
						<view class="cart-item">
							<view class="cart-goods-items">
								<view class="goods-item" v-for="(item,childIndex) in lists" :key="childIndex">
									<image @click="changeDx(item)"
										:src="item.selected==1?'/static/common/checkbox_select.png':'/static/common/checkbox_unselect.png'"
										class="check-img" mode="widthFix" />
									<image :src="item.goods_img" class="goods-img" mode="aspectFit" />
									<view class="goods-item-right">
										<view class="goods-name">{{item.goods_name}}</view>
										<view class="goods-spec">已选:{{item.item_name?item.item_name:'无'}}</view>
										<view class="goods-right">
											<view class="goods-price">
												<text>¥</text>
												<text class="jiage">{{item.goods_price}}</text>
											</view>
											<view class="goods-num-box">
												<text :class="{'dis':item.goods_num<=1}"
													@click="changeNum(item,-1)">-</text>
												<text class="number">{{item.goods_num}}</text>
												<text :class="{'dis':item.goods_num>=item.max}"
													@click="changeNum(item,1)">+</text>
											</view>
										</view>
									</view>
								</view>
							</view>
						</view>
						<view style="height: 20rpx;"></view>
					</view>
				</scroll-view>
				<view class="cart-list-bottom">
					<view class="bottom-info">
						<view class="left">
							<view class="gl-text" @click="changeText">{{text}}</view>
							<block v-if="text=='管理'">
								<view class="center">合计</view>
								<view class="amount">
									<text>¥</text>
									<text class="jiage">{{amount}}</text>
								</view>
							</block>
						</view>
						<button class="submit-btn" @click="submit" :disabled="submitDisabled || delDisabled">{{text=='管理'?'结算':'删除'}}</button>
					</view>
				</view>
			</block>
			<view class="empty-container" v-else>
				<u-empty text="购物车暂无数据" :icon="emptyIcon" />
			</view>
		</block>
		
		<wxLogin ref="wx_login" @loginAfter="loginAfter"></wxLogin>
	</view>
</template>

<script>
	import wxLogin from "@/components/wx-login/wx-login.vue"
	var _this;
	export default {
		data() {
			return {
				//导航栏高度
				navBarHeight: 44,
				statusbarH:10,
				text:"管理",
				delDisabled: false,
				loginDisabled:false,
				loginShow:false,
			};
		},
		onNavigationBarButtonTap(e) {
			// #ifdef H5
			var text = document.getElementsByClassName('uni-btn-icon')[1].innerHTML
			if (text == '编辑') {
				if (this.lists.length == 0) {
					return;
				}
				document.getElementsByClassName('uni-btn-icon')[1].innerHTML = '完成'
			} else {
				document.getElementsByClassName('uni-btn-icon')[1].innerHTML = '编辑'
			}
			// #endif
			// #ifdef APP-PLUS
			var currentWebview = this.$mp.page.$getAppWebview();
			currentWebview.setTitleNViewButtonStyle(0, {
				text: _this.rightText == '编辑' ? '完成' : '编辑'
			});
			if (_this.rightText == '编辑') {
				this.show = true
			} else {
				this.show = false
			}
			_this.rightText = _this.rightText == '编辑' ? '完成' : '编辑'
			// #endif
		},
		methods: {
			changeText(){
				_this.text=_this.text=='管理'?'完成':'管理'
			},
			async get_cart_list() {
				const data = await _this.$post('port/cart_list')
				if (data.code == 200) {
					_this.lists = data.result.cart_list
				} else {
					this.$u.toast(data.msg)
				}
				if (_this.load) {
					_this.load = false
				}
				setTimeout(()=>{
					uni.stopPullDownRefresh()
				},1000)
			},
			showLogin(){
				_this.$refs.wx_login.loginShow = true
			},
			loginAfter(result){
				_this.get_cart_list()
			},
			changeDx(item) {
				item.selected = item.selected == 0 ? 1 : 0
				_this.doCart()
			},
			selectAll() {
				var checkAll = _this.checkAll
				if (_this.lists.length > 0) {
					for (let i = 0; i < _this.lists.length; i++) {
						var item = _this.lists[i]
						item.is_checked = !checkAll
						for (let j = 0; j < item.child.length; j++) {
							let child = item.child[j]
							child.selected = checkAll ? 0 : 1
						}
					}
				}
				_this.doCart()
			},
			changeNum(item, step) {
				var number = item.goods_num + step
				if (step < 0) {
					if (number < 1) {
						return
					}
					item.goods_num = number
					if (item.selected == 0) item.selected = 1
					_this.doCart()
				} else {
					if (number > item.store_count) {
						return;
					}
					item.goods_num = number
					if (item.selected == 0) item.selected = 1
					_this.doCart()
				}
			},
			checkTitle(item) {
				let selected = !item.is_checked;
				for (let j = 0; j < item.child.length; j++) {
					let child = item.child[j];
					child.selected = selected ? 1 : 0;
				}
				item.is_checked = !item.is_checked;
			},
			async doCart() {
				var items = []
				if (_this.lists.length > 0) {
					for (let i = 0; i < _this.lists.length; i++) {
						var item = _this.lists[i]
						let one = {}
						one.id = item.id
						one.selected = item.selected
						one.goods_num = item.goods_num
						items.push(one)
					}
				}
				const params = {
					cart: JSON.stringify(items),
				}
				const data = await _this.$post('port/cart_do', params)
				if (data.code == 200) {
					// this.$u.toast(data.msg)
				} else {
					this.$u.toast(data.msg)
				}
			},
			async submit() {
				if(_this.text=='管理'){
					var url = `/pages/cart/cart-submit?action=cart`;
					_this.toNext(url)
				}else{
					uni.showModal({
						title:'提示',
						content:'确认删除?',
						success(res) {
							if(res.confirm){
								_this.delCart()
							}
						}
					})
				}
			},
			async delCart(){
				var items = []
				if (_this.lists.length > 0) {
					for (let i = 0; i < _this.lists.length; i++) {
						var item = _this.lists[i]
						if(item.selected==1){
							items.push(item.id)
						}
					}
					const params = {
						"ids": items.join(','),
					}
					const data = await _this.$post('port/del_cart', params)
					if(data.code==200){
						this.$u.toast(data.msg)
						_this.get_cart_list()
					}else{
						this.$u.toast(data.msg)
					}
				}
			}
		},
		onLoad(e) {
			_this = this;
			let sysInfo = uni.getSystemInfoSync();
			_this.statusbarH=sysInfo.statusBarHeight
			// #ifdef MP-WEIXIN
			// 胶囊信息
			let menu = uni.getMenuButtonBoundingClientRect();
			// 导航栏高度
			let navBarHeight = menu.height + 10;
			this.navBarHeight = navBarHeight
			// #endif
		},
		onShow() {
			if (this.user_id==0) {
				setTimeout(()=>{
					_this.load = false
				},1000)
			}else{
				_this.get_cart_list()
			}
		},
		onPullDownRefresh() {
			if (this.user_id==0) {
				setTimeout(()=>{
					uni.stopPullDownRefresh()
				},1000)
			}else{
				_this.get_cart_list()
			}
		},
		components:{
			wxLogin
		},
		computed: {
			amount: {
				cache: false,
				get() {
					var amount = 0;
					if(this.lists==''){
						return amount;
					}
					if (this.lists.length > 0) {
						for (let i = 0; i < _this.lists.length; i++) {
							var item = this.lists[i]
							if (item.selected == 1) {
								amount += parseFloat(item.goods_price * item.goods_num)
							}
						}
					}
					return amount.toFixed(2)
				}
			},
			checkAll: {
				cache: false,
				get() {
					var checkAll = true;
					if (this.lists.length > 0) {
						for (let i = 0; i < this.lists.length; i++) {
							var item = this.lists[i]
							if (item.selected != 1) {
								checkAll = false
								break
							}
						}
					}
					return checkAll
				}
			},
			submitDisabled: {
				cache: false,
				get() {
					var disabled = true;
					if (this.lists.length > 0) {
						for (let i = 0; i < this.lists.length; i++) {
							var item = this.lists[i]
							if (item.selected == 1) {
								disabled = false
								break
							}
						}
					}
					return disabled
				}
			}
		}
	}
</script>

<style lang="scss" scoped>
	@import "static/css/order.scss";

	.container {
		height: 100%;
		position: relative;
		.denglu{
			width: 100%;
			height: 100%;
			@include flex-box(row,center,center);
			.login-btn{
				background: $bg-btn;
				color: #fff;
				font-size: 30rpx;
				width: 50%;
			}
		}
		.scroll {
			height: calc(100% - #{$bottom-h} - 10rpx);

			.cart-container {
				padding: 20rpx 30rpx 0 30rpx;
				.cart-item{
					background: none;
					padding: 0;
					.cart-goods-items{
						.goods-item{
							border-radius: $border-radius;
							background: #fff;
							min-height: 220rpx;
							border-bottom: none;
							&:not(:last-child){
								margin-bottom: 20rpx;
							}
							.goods-item-right{
								justify-content: space-evenly;
							}
						}
					}
				}
			}
		}

		.cart-list-bottom {
			/* #ifdef H5 */
			bottom: 50px;
			/* #endif */
			/* #ifndef H5 */
			bottom: 0;
			/* #endif */
			.left{
				flex: 1;
				.gl-text{
					flex: 1;
				}
			}
		}
	}
</style>